/**
 * @distilled.cloud/paperless-ngx — Paperless-ngx REST API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * in `.generated-specs` (written by `scripts/convert.ts` from Paperless-ngx's
 * own served OpenAPI 3.0.3 document, pinned to v3.1.1 — see
 * codegen/manifest.json's `paperless-openapi` entry in homeflare-kit — split
 * by the document's own `tags`). Everything else in this folder is
 * hand-written.
 *
 * One module per Paperless-ngx API tag — `documents`, `correspondents`,
 * `tags`, `document_types`, `storage_paths`, `custom_fields`,
 * `saved_views`, `share_links`, `share_link_bundles`, `workflows`,
 * `workflow_triggers`, `workflow_actions`, `mail_accounts`, `mail_rules`,
 * `processed_mail`, `users`, `groups`, `profile`, `tasks`, `trash`,
 * `bulk_edit_objects`, `logs`, `config`, `ui_settings`, `search`,
 * `statistics`, `status`, `remote_version`, `oauth`, `token` — the same
 * split Paperless-ngx's own API browser uses.
 *
 * @example
 * ```ts
 * import * as PaperlessNgx from "@distilled.cloud/paperless-ngx";
 *
 * const tags = yield* PaperlessNgx.Services.tags.tagsList({});
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  PaperlessNgxProtocol,
  type PaperlessNgxOpError,
  type PaperlessNgxOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
